function opisz(zawod) {
  return `${this.imie} pracuje jako ${zawod}`;
}

console.log(opisz.call({ imie: "Tomek" }, "programista")); // "Tomek pracuje jako programista"
console.log(opisz.call({ imie: "Zosia" }, "lekarka"));      // "Zosia pracuje jako lekarka"

function policzRabat(procent) {
  return this.cena - (this.cena * procent) / 100;
}

console.log(policzRabat.call({ cena: 200 }, 10)); // 180

function przedstawZWiekiem(miasto) {
  return `${this.imie} (${this.wiek} lat) z ${miasto}`;
}

console.log(przedstawZWiekiem.call({ imie: "Ala", wiek: 30 }, "Gdansk"));
// "Ala (30 lat) z Gdansk"
console.log(przedstawZWiekiem.call({ imie: "Piotr", wiek: 45 }, "Poznan"));
// "Piotr (45 lat) z Poznan"

function pelnaCena() {
  return this.cenaNetto * (1 + this.vat);
}

console.log(pelnaCena.call({ cenaNetto: 100, vat: 0.23 })); // 123

function przywitaj(pora) {
  return `${pora}, ${this.imie}!`;
}

const osoby = [{ imie: "Ala" }, { imie: "Bartek" }, { imie: "Celina" }];

for (const osoba of osoby) {
  console.log(przywitaj.call(osoba, "Dzien dobry"));
}
// "Dzien dobry, Ala!"
// "Dzien dobry, Bartek!"
// "Dzien dobry, Celina!"

function obliczBMI() {
  return this.waga / (this.wzrost * this.wzrost);
}

console.log(obliczBMI.call({ waga: 70, wzrost: 1.75 }).toFixed(2)); // "22.86"

function przedstawSie(miasto, kraj) {
  console.log(`${this.name} mieszka w ${miasto}, ${kraj}`);
}

// Zapomniany thisArg - "Krakow" staje sie (blednie) wartoscia this:
przedstawSie.call("Krakow", "Polska");
// Blad: Cannot read properties of undefined (reading 'name')
// (lub inne zachowanie w zaleznosci od trybu) - "Krakow" (string) staje
// sie this, wiec this.name probuje odczytac "name" ze stringa "Krakow",
// co zwraca undefined. "Polska" staje sie JEDYNYM przekazanym argumentem
// (miasto), a kraj pozostaje undefined - kompletnie inny wynik niz
// zamierzony.

function powitaj(zwrot) {
  return zwrot + ", " + this.imie + "!";
}

console.log(powitaj.call({ imie: "Ala" }, "Czesc")); // -> "Czesc, Ala!"
console.log(powitaj.call({ imie: "Jan" }, "Czesc")); // -> "Czesc, Jan!"

function sumuj(a, b) {
  return this.baza + a + b;
}

console.log(sumuj.call({ baza: 10 }, 1, 2)); // -> 13

const a = {
  n: "a",
  pokaz() {
    return "to " + this.n;
  }
};
const b = { n: "b" };

console.log(a.pokaz());       // -> "to a"
console.log(a.pokaz.call(b)); // -> "to b"
// call ustawil this na b, wiec this.n to "b".

const podobny = { 0: "x", 1: "y", length: 2 };
const wynik = Array.prototype.map.call(podobny, s => s + s);
console.log(wynik); // -> ["xx", "yy"]

function maWlasny(obiekt, klucz) {
  return Object.prototype.hasOwnProperty.call(obiekt, klucz);
}

console.log(maWlasny({ a: 1 }, "a"));        // -> true
console.log(maWlasny({ a: 1 }, "toString")); // -> false

function typDokladny(x) {
  return Object.prototype.toString.call(x);
}

console.log(typDokladny([]));              // -> "[object Array]"
console.log(typDokladny(null));            // -> "[object Null]"
console.log(typDokladny(1));               // -> "[object Number]"
console.log(typDokladny("a"));             // -> "[object String]"
console.log(typDokladny(function () {}));  // -> "[object Function]"
console.log(typDokladny(undefined));       // -> "[object Undefined]"

function Osoba(imie) {
  this.imie = imie;
}

function Pracownik(imie, stanowisko) {
  Osoba.call(this, imie);
  this.stanowisko = stanowisko;
}

const p = new Pracownik("Ala", "programistka");
console.log(p.imie);        // -> "Ala"
console.log(p.stanowisko);  // -> "programistka"

function bezPierwszego() {
  return Array.prototype.slice.call(arguments, 1);
}

console.log(bezPierwszego(1, 2, 3)); // -> [2, 3]

function ustaw(pole, wartosc) {
  this[pole] = wartosc;
}

const a = {};
const b = {};
ustaw.call(a, "x", 1);
ustaw.call(b, "y", 2);

console.log(a); // -> { x: 1 }
console.log(b); // -> { y: 2 }

"use strict";

function f() {
  return typeof this;
}

console.log(f.call(5));    // -> "number"
console.log(f.call("a"));  // -> "string"

function g() {
  return this === null;
}
console.log(g.call(null)); // -> true

"use strict";

function przedstawSie(miasto, kraj) {
  return this + " mieszka w " + miasto + ", " + kraj;
}

console.log(przedstawSie.call("Krakow", "Polska"));
// -> "Krakow mieszka w Polska, undefined" - "Krakow" zostalo this, a "Polska" pierwszym argumentem

function zwykla() {
  return this.n;
}
const strzalka = () => typeof this;

console.log(zwykla.call({ n: 5 })); // -> 5
console.log(strzalka.call({ n: 5 }) === strzalka()); // -> true (call nie zmienil this strzalki)

function wywolajZ(fn, obiekt, ...args) {
  return fn.call(obiekt, ...args);
}

function opisz(a, b) {
  return this.n + a + b;
}

console.log(wywolajZ(opisz, { n: 1 }, 2, 3)); // -> 6

function f1() { return this.n; }
function f2() { return this.n * 2; }

const obiekt = { n: 4 };
console.log([f1, f2].map(fn => fn.call(obiekt))); // -> [4, 8]

function przedstaw(glos) {
  return this.imie + " mowi " + glos;
}

const kot = { imie: "Filemon" };
const pies = { imie: "Burek" };

console.log(przedstaw.call(kot, "miau")); // -> "Filemon mowi miau"
console.log(przedstaw.call(pies, "hau")); // -> "Burek mowi hau"

function zwieksz() {
  this.n++;
}

const licznik = { n: 0 };
zwieksz.call(licznik);
zwieksz.call(licznik);
zwieksz.call(licznik);

console.log(licznik.n); // -> 3

"use strict";

function pokaz() {
  return this.imie;
}
const osoba = { imie: "Ola" };

try {
  pokaz();
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

console.log(pokaz.call(osoba)); // -> "Ola"

const znaki = [];
Array.prototype.forEach.call("ab", znak => znaki.push(znak));
console.log(znaki); // -> ["a", "b"]

function ile() {
  return arguments.length;
}

console.log(ile.call({}, 1, 2, 3)); // -> 3
// thisArg nie jest liczony jako argument funkcji.

function pelneImie() {
  return this.imie + " " + this.nazwisko;
}

const a = { imie: "Ala", nazwisko: "Nowak" };
const b = { imie: "Jan", nazwisko: "Kowalski" };

console.log(pelneImie.call(a)); // -> "Ala Nowak"
console.log(pelneImie.call(b)); // -> "Jan Kowalski"
// call wywoluje funkcje NATYCHMIAST z jawnie podanym this i zwraca jej wynik.

